using HomeLibrary;
using System.Text.Json;
public static class CompleteRecoveryTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception("Complete recovery: "+message);Console.WriteLine("PASS "+message);}
 sealed class Host:IRecoveryHost {public int Starts,Stops,Prepares;public bool FailFirstHealth,FailPrepare,FailAllHealth;public Task Stop(CancellationToken s){Stops++;return Task.CompletedTask;}public Task Start(CancellationToken s){Starts++;return Task.CompletedTask;}public Task<bool> Healthy(CancellationToken s)=>Task.FromResult(!FailAllHealth&&(!FailFirstHealth||Starts>1));public void PrepareData(string d){Prepares++;if(FailPrepare)throw new IOException("injected permission failure");}}
 static (string live,string work,string candidate,Host host,CompleteRecovery core) Fixture(string root){Directory.CreateDirectory(root);var live=Path.Combine(root,"data");var work=Path.Combine(root,"private-recovery");var candidate=Path.Combine(work,"candidate");Directory.CreateDirectory(live);Directory.CreateDirectory(candidate);File.WriteAllText(Path.Combine(live,"library.sqlite"),"CURRENT DATA");File.WriteAllText(Path.Combine(live,"account-secret"),"CURRENT SECRET");File.WriteAllText(Path.Combine(candidate,"library.sqlite"),"BACKUP DATA");var host=new Host();return(live,work,candidate,host,new(live,work,host));}
 static string Data(string dir)=>File.ReadAllText(Path.Combine(dir,"library.sqlite"));
 static async Task Reject(Func<Task> work,string message){try{await work();throw new Exception("Expected failure "+message);}catch(Exception e)when(e is LibraryError or IOException){Console.WriteLine("PASS "+message);}}
 public static async Task Run(string root){
  var platform=OperatingSystem.IsWindows()?"Windows":"Linux";
  BackupVerificationReport Report(int patch,int format=7,bool portable=false,string? host=null)=>new(true,1,1,$"2.0.{patch}-preview",format,"fixture",host??platform,false,true,portable);
  foreach(var patch in Enumerable.Range(53,7))Check(RecoveryCompatibility.CanRestore(Report(patch)),"format-7 complete backup accepts supported 2.0."+patch);
  foreach(var patch in new[]{52,60,99})Check(!RecoveryCompatibility.CanRestore(Report(patch)),"complete backup rejects unsupported format/version combination 2.0."+patch);
  Check(RecoveryCompatibility.CanRestore(Report(43,4))&&RecoveryCompatibility.CanRestore(Report(45,5))&&RecoveryCompatibility.CanRestore(Report(47,6)),"previous supported complete archive cohorts remain available");
  Check(!RecoveryCompatibility.CanRestore(Report(59,host:"other-platform"))&&RecoveryCompatibility.CanRestore(Report(59,portable:true,host:"other-platform")),"cross-platform complete recovery requires portable archive");
  Check(!RecoveryCompatibility.CanRestore(Report(59) with{Verified=false})&&!RecoveryCompatibility.CanRestore(Report(59) with{SupportedLibraryFormat=false})&&!RecoveryCompatibility.CanRestore(Report(59) with{Version="2.0.59.1"}),"unverified, unsupported and unknown revision backups remain blocked");
  var f=Fixture(Path.Combine(root,"success"));var retained=await f.core.Restore(f.candidate);Check(Data(f.live)=="BACKUP DATA"&&Data(retained)=="CURRENT DATA"&&File.ReadAllText(Path.Combine(retained,"account-secret"))=="CURRENT SECRET","successful replacement retains the entire old data and credentials");Check(File.Exists(Path.Combine(f.live,CompleteRecovery.ReviewMarker)),"restored historical data requires local access review before remote use");Check(f.core.Pending()==null&&f.host.Starts==1&&f.host.Stops==1,"successful restore checks startup and completes its journal");
  f=Fixture(Path.Combine(root,"health-failure"));f.host.FailFirstHealth=true;await Reject(async()=>{await f.core.Restore(f.candidate);},"failed startup attempts undo");Check(Data(f.live)=="CURRENT DATA"&&f.core.Pending()==null&&Directory.GetDirectories(f.work,"failed-*").Any(x=>Data(x)=="BACKUP DATA"),"failed candidate is retained and the original library is put back");
  f=Fixture(Path.Combine(root,"undo-failure"));f.host.FailAllHealth=true;await Reject(async()=>{await f.core.Restore(f.candidate);},"failed restore and failed undo retain an actionable journal");Check(f.core.Pending()!=null&&Data(f.live)=="CURRENT DATA","undo startup failure never deletes the returned original records");f.host.FailAllHealth=false;await f.core.Undo();Check(f.core.Pending()==null&&Data(f.live)=="CURRENT DATA","reopening and retrying interrupted undo succeeds");
  f=Fixture(Path.Combine(root,"permissions"));f.host.FailPrepare=true;await Reject(async()=>{await f.core.Restore(f.candidate);},"permission failure happens before moving current data");Check(Data(f.live)=="CURRENT DATA"&&!File.Exists(f.core.JournalFile),"preflight failure leaves the current directory intact");
  foreach(var phase in new[]{"moving-current","installing-backup","starting","undo-installing-current"}){
   f=Fixture(Path.Combine(root,phase));var old=Path.Combine(f.work,"before");var failed=Path.Combine(f.work,"failed");if(phase is "installing-backup" or "starting")Directory.Move(f.live,old);if(phase=="starting")Directory.Move(f.candidate,f.live);
   File.WriteAllText(f.core.JournalFile,JsonSerializer.Serialize(new RecoveryJournal(f.live,old,failed,phase,DateTimeOffset.UtcNow.ToString("O")),Library.Json));
   await Reject(async()=>{await f.core.Restore(f.candidate);},"pending "+phase+" blocks another restore");await f.core.Undo();Check(Data(f.live)=="CURRENT DATA"&&f.core.Pending()==null,"interrupted "+phase+" is safely undone without deleting data");
  }
  f=Fixture(Path.Combine(root,"malicious-path"));File.WriteAllText(f.core.JournalFile,JsonSerializer.Serialize(new RecoveryJournal(f.live,Path.Combine(root,"outside"),Path.Combine(f.work,"failed"),"starting","now"),Library.Json));await Reject(()=>{f.core.Pending();return Task.CompletedTask;},"journal traversal outside protected work root is rejected");Check(Data(f.live)=="CURRENT DATA","invalid journal leaves live data unchanged");
  f=Fixture(Path.Combine(root,"open-server"));using(var locked=new FileStream(Path.Combine(f.live,"local-admin.lock"),FileMode.Create,FileAccess.ReadWrite,FileShare.None)){await Reject(async()=>{await f.core.Restore(f.candidate);},"open server lock blocks directory replacement");}Check(Data(f.live)=="CURRENT DATA","open-server rejection retains current records");
  f=Fixture(Path.Combine(root,"notifications"));foreach(var n in new[]{"reminder-settings.protected","web-push.protected"})File.WriteAllText(Path.Combine(f.candidate,n),"RECOVERED CONFIG");CompleteRecovery.PauseNotifications(f.candidate);Check(!File.Exists(Path.Combine(f.candidate,"reminder-settings.protected"))&&!File.Exists(Path.Combine(f.candidate,"web-push.protected"))&&Directory.GetFiles(f.candidate,"*.paused-by-recovery-*").Length==2,"recovered notification configuration is retained under paused names");
  if(OperatingSystem.IsLinux()){var link=Path.Combine(f.candidate,"escape");File.CreateSymbolicLink(link,Path.Combine(f.live,"account-secret"));await Reject(()=>{CompleteRecovery.AssertTree(f.candidate);return Task.CompletedTask;},"linked files are rejected before recovery copy or replacement");File.Delete(link);}
  Check(RecoveryPlatform.Banner("<html><body class='login'><main>hello</main></body></html>").Contains("RECOVERY TEST"),"test banner is inserted on login and dashboard pages");
 }
}
